//! Shared HTTP transport for the providers built on `reqwest`.
//!
//! Anthropic and OpenAI publish no Rust SDKs, so their providers talk HTTP directly. This module is
//! the part of the official Anthropic and OpenAI SDKs (both generated by Stainless) that the
//! providers rely on:
//!
//! - [`HttpTransport::post`] sends a JSON request with the SDK retry policy: up to `max_retries`
//!   retries (2 by default) on connection errors, timeouts, 408, 409, 429 and 5xx responses,
//!   obeying `x-should-retry`, waiting `retry-after-ms` or `retry-after` when the server sends them
//!   and otherwise backing off exponentially from 0.5 s to 8 s with up to 25 % jitter. The timeout
//!   (10 minutes by default) covers each attempt until the response headers arrive; a streamed body
//!   is not timed.
//! - [`sse_events`] turns a streaming response into server-sent events, and [`json_body`] reads a
//!   JSON response.
//! - [`HttpError`] carries what a provider maps to SDK errors: the HTTP status, the decoded error
//!   body and the SDK's error message text (`"<status> <body>"`, `"Connection error."`,
//!   `"Request timed out."`).
//!
//! The module knows nothing about a provider's endpoints, headers or event payloads. A provider
//! builds an [`HttpTransport`] with its base URL and default headers (authentication, API
//! version), names the part of an error body its SDK puts in the message ([`ErrorPayload`]), and
//! parses the events itself. Tests inject the sleeper and the jitter source so no test waits for
//! real.

use std::sync::Arc;
use std::time::Duration;

use eventsource_stream::{EventStreamError, Eventsource};
use futures::StreamExt;
use reqwest::header::{HeaderMap, HeaderName, HeaderValue};

use super::model::BoxStream;
use crate::error::BoxError;
use crate::retry::{Sleeper, TokioSleeper};
use crate::types::JsonValue;

/// Retries after the first attempt when the provider config sets none (the SDK default).
pub(crate) const DEFAULT_MAX_RETRIES: u32 = 2;

/// Time allowed for each attempt until the response headers arrive (SDK `DEFAULT_TIMEOUT`).
pub(crate) const DEFAULT_TIMEOUT: Duration = Duration::from_secs(600);

const INITIAL_RETRY_DELAY_SECONDS: f64 = 0.5;
const MAX_RETRY_DELAY_SECONDS: f64 = 8.0;
const MAX_JITTER: f64 = 0.25;

/// Which part of an error response body the provider's SDK builds the error message from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[allow(dead_code, reason = "each provider reads one payload")]
pub(crate) enum ErrorPayload {
    /// The whole body (Anthropic: `{"type": "error", "error": {..}}`).
    Body,
    /// The body's `error` field (OpenAI: `{"error": {"message": ..}}`).
    ErrorField,
}

/// What an [`HttpError`] is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum HttpErrorKind {
    /// The server answered with a non-success status (SDK `APIError` with a status).
    Status(u16),
    /// The connection failed before or while the response was read (SDK `APIConnectionError`).
    Connection,
    /// No response headers arrived within the timeout (SDK `APIConnectionTimeoutError`).
    Timeout,
    /// The stream carried an `error` event (SDK `APIError` without a status).
    Event,
    /// The response could not be decoded, such as event data that is not JSON. The SDKs throw
    /// a plain error here, not an `APIError`.
    Decode,
    /// The API key could not be resolved before sending (the OpenAI SDK's `OpenAIError` from an
    /// API key function), so no request was made.
    Credentials,
    /// The request could not be built, such as from an invalid base URL or header value, so no
    /// request was made. Never retried.
    Request,
}

/// A failed HTTP exchange, with the message text the official provider SDKs give it.
#[derive(Debug, thiserror::Error)]
#[error("{message}")]
pub(crate) struct HttpError {
    kind: HttpErrorKind,
    message: String,
    body: Option<JsonValue>,
    #[source]
    source: Option<BoxError>,
}

impl HttpError {
    /// An error response (SDK `APIError.generate`). `body` is the decoded JSON body, `text` the raw
    /// body when it is not JSON.
    pub(crate) fn status(status: u16, body: Option<JsonValue>, text: &str, payload: ErrorPayload) -> Self {
        let error = body.as_ref().and_then(|body| match payload {
            ErrorPayload::Body => Some(body),
            ErrorPayload::ErrorField => body.get("error"),
        });
        let text = body.is_none().then_some(text);
        Self {
            kind: HttpErrorKind::Status(status),
            message: api_error_message(Some(status), error, text),
            body,
            source: None,
        }
    }

    /// An `error` event in a stream; `data` is the event data, decoded when it is JSON.
    #[allow(dead_code, reason = "the Anthropic provider reads error events")]
    pub(crate) fn event(data: &str) -> Self {
        let body = serde_json::from_str(data).unwrap_or_else(|_| JsonValue::String(data.to_owned()));
        Self {
            kind: HttpErrorKind::Event,
            message: api_error_message(None, Some(&body), None),
            body: Some(body),
            source: None,
        }
    }

    /// An error object carried in a stream event's data (`{"error": {..}}`), which the OpenAI SDK
    /// raises as an `APIError` without a status; `data` is kept as the body.
    #[allow(dead_code, reason = "the OpenAI provider reads error objects in its streams")]
    pub(crate) fn event_error_field(data: JsonValue) -> Self {
        let message = api_error_message(None, data.get("error"), None);
        Self {
            kind: HttpErrorKind::Event,
            message,
            body: Some(data),
            source: None,
        }
    }

    /// The API key could not be resolved; `message` is the SDK's text.
    #[allow(dead_code, reason = "the OpenAI provider resolves API keys per request")]
    pub(crate) fn credentials(message: impl Into<String>, source: Option<BoxError>) -> Self {
        Self {
            kind: HttpErrorKind::Credentials,
            message: message.into(),
            body: None,
            source,
        }
    }

    /// A request that could not be built; `message` says what is invalid and never holds a header
    /// value, which may be a credential.
    pub(crate) fn request(message: impl Into<String>, source: Option<BoxError>) -> Self {
        Self {
            kind: HttpErrorKind::Request,
            message: message.into(),
            body: None,
            source,
        }
    }

    /// A connection failure (SDK `APIConnectionError`, `"Connection error."`).
    pub(crate) fn connection(source: impl Into<BoxError>) -> Self {
        Self {
            kind: HttpErrorKind::Connection,
            message: "Connection error.".to_owned(),
            body: None,
            source: Some(source.into()),
        }
    }

    /// A timeout waiting for the response (SDK `APIConnectionTimeoutError`, `"Request timed out."`).
    pub(crate) fn timeout() -> Self {
        Self {
            kind: HttpErrorKind::Timeout,
            message: "Request timed out.".to_owned(),
            body: None,
            source: None,
        }
    }

    /// A response that could not be decoded.
    pub(crate) fn decode(message: impl Into<String>, source: impl Into<BoxError>) -> Self {
        Self {
            kind: HttpErrorKind::Decode,
            message: message.into(),
            body: None,
            source: Some(source.into()),
        }
    }

    /// What the error is.
    #[allow(dead_code, reason = "tests and the OpenAI provider branch on it")]
    pub(crate) fn kind(&self) -> HttpErrorKind {
        self.kind
    }

    /// The HTTP status, for an error response.
    pub(crate) fn status_code(&self) -> Option<u16> {
        match self.kind {
            HttpErrorKind::Status(status) => Some(status),
            _ => None,
        }
    }

    /// The SDK message text.
    pub(crate) fn message(&self) -> &str {
        &self.message
    }

    /// The decoded error body (SDK `APIError.error`).
    pub(crate) fn body(&self) -> Option<&JsonValue> {
        self.body.as_ref()
    }

    /// Whether the SDK would raise this as an `APIError` (every kind but
    /// [`HttpErrorKind::Decode`], [`HttpErrorKind::Credentials`] and [`HttpErrorKind::Request`]).
    #[allow(dead_code, reason = "the Anthropic provider falls back on API errors")]
    pub(crate) fn is_api_error(&self) -> bool {
        !matches!(
            self.kind,
            HttpErrorKind::Decode | HttpErrorKind::Credentials | HttpErrorKind::Request
        )
    }

    /// Whether the connection failed or timed out, which providers report as `ModelNetworkError`.
    pub(crate) fn is_network(&self) -> bool {
        matches!(self.kind, HttpErrorKind::Connection | HttpErrorKind::Timeout)
    }
}

/// The SDK's `APIError.makeMessage`: `"<status> <message>"`, where the message is the payload's
/// `message`, else the payload as JSON, else the raw body text.
fn api_error_message(status: Option<u16>, error: Option<&JsonValue>, text: Option<&str>) -> String {
    let message = match error {
        Some(error) => match error.get("message") {
            Some(JsonValue::String(message)) if !message.is_empty() => Some(message.clone()),
            Some(message) if is_truthy(message) => Some(message.to_string()),
            _ => Some(error.to_string()),
        },
        None => text.map(str::to_owned),
    }
    .filter(|message| !message.is_empty());
    match (status, message) {
        (Some(status), Some(message)) => format!("{status} {message}"),
        (Some(status), None) => format!("{status} status code (no body)"),
        (None, Some(message)) => message,
        (None, None) => "(no status code or body)".to_owned(),
    }
}

/// Whether a JSON value counts as set: not `null`, `false`, zero or an empty string.
fn is_truthy(value: &JsonValue) -> bool {
    match value {
        JsonValue::Null => false,
        JsonValue::Bool(value) => *value,
        JsonValue::Number(number) => number.as_f64().is_some_and(|number| number != 0.0),
        JsonValue::String(text) => !text.is_empty(),
        JsonValue::Array(_) | JsonValue::Object(_) => true,
    }
}

/// How an [`HttpTransport`] reaches a provider.
#[derive(Debug, Clone)]
pub(crate) struct HttpTransportConfig {
    /// The API base URL, such as `https://api.anthropic.com`; paths are appended to it.
    pub(crate) base_url: String,
    /// Headers sent with every request; a request's own headers replace those of the same name.
    pub(crate) default_headers: HeaderMap,
    /// Retries after the first attempt.
    pub(crate) max_retries: u32,
    /// Time allowed for each attempt until the response headers arrive.
    pub(crate) timeout: Duration,
    /// The part of an error body the provider's SDK builds error messages from.
    pub(crate) error_payload: ErrorPayload,
}

/// Source of jitter in `[0, 1)` (the SDKs' `Math.random`).
pub(crate) type Random = Arc<dyn Fn() -> f64 + Send + Sync>;

/// A provider's HTTP endpoint with the SDK retry policy. Cheap to clone.
#[derive(Clone)]
pub(crate) struct HttpTransport {
    client: reqwest::Client,
    config: Arc<HttpTransportConfig>,
    sleeper: Arc<dyn Sleeper>,
    random: Random,
}

impl std::fmt::Debug for HttpTransport {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("HttpTransport")
            .field("base_url", &self.config.base_url)
            .field("max_retries", &self.config.max_retries)
            .field("timeout", &self.config.timeout)
            .finish_non_exhaustive()
    }
}

impl HttpTransport {
    /// Creates the transport.
    ///
    /// # Errors
    ///
    /// Returns a request error when the base URL is not an absolute `http` or `https` URL or the
    /// HTTP client cannot be built (no TLS backend).
    pub(crate) fn new(config: HttpTransportConfig) -> Result<Self, HttpError> {
        validate_base_url(&config.base_url)?;
        let client = reqwest::Client::builder().build().map_err(|error| {
            HttpError::request(format!("could not build the http client: {error}"), Some(error.into()))
        })?;
        Ok(Self {
            client,
            config: Arc::new(config),
            sleeper: Arc::new(TokioSleeper),
            random: Arc::new(rand::random::<f64>),
        })
    }

    /// Replaces how the transport waits between attempts.
    #[must_use]
    #[allow(dead_code, reason = "tests wait without sleeping")]
    pub(crate) fn with_sleeper(mut self, sleeper: Arc<dyn Sleeper>) -> Self {
        self.sleeper = sleeper;
        self
    }

    /// Replaces the jitter source.
    #[must_use]
    #[allow(dead_code, reason = "tests fix the jitter")]
    pub(crate) fn with_random(mut self, random: Random) -> Self {
        self.random = random;
        self
    }

    /// The URL of `path` under the base URL.
    fn url(&self, path: &str) -> String {
        format!(
            "{}/{}",
            self.config.base_url.trim_end_matches('/'),
            path.trim_start_matches('/')
        )
    }

    /// POSTs `body` as JSON to `path`, retrying as the SDKs do, and returns the successful
    /// response with its body unread. `headers` replace default headers of the same name.
    ///
    /// # Errors
    ///
    /// Returns the last attempt's error once it is not retryable or no retries remain: an error
    /// response with its body read, a connection error or a timeout.
    pub(crate) async fn post(
        &self,
        path: &str,
        body: &JsonValue,
        headers: &HeaderMap,
    ) -> Result<reqwest::Response, HttpError> {
        let url = self.url(path);
        let mut request_headers = self.config.default_headers.clone();
        for (name, value) in headers {
            request_headers.insert(name.clone(), value.clone());
        }
        let max_retries = self.config.max_retries;
        let mut retries_remaining = max_retries;
        loop {
            let send = self
                .client
                .post(&url)
                .headers(request_headers.clone())
                .json(body)
                .send();
            let outcome = tokio::time::timeout(self.config.timeout, send).await;
            let error = match outcome {
                Ok(Ok(response)) if response.status().is_success() => return Ok(response),
                Ok(Ok(response)) => {
                    let status = response.status().as_u16();
                    let retry = should_retry(status, response.headers());
                    if retry && retries_remaining > 0 {
                        let delay = retry_delay(
                            Some(response.headers()),
                            retries_remaining,
                            max_retries,
                            self.random.as_ref(),
                        );
                        drop(response);
                        tracing::debug!(
                            "status=<{status}>, retries_remaining=<{retries_remaining}> | request failed, retrying"
                        );
                        self.sleeper.sleep(delay).await;
                        retries_remaining -= 1;
                        continue;
                    }
                    return Err(status_error(response, self.config.error_payload).await);
                }
                Ok(Err(error)) if error.is_builder() => {
                    return Err(HttpError::request(
                        format!("could not build the request to {url}"),
                        Some(error.into()),
                    ));
                }
                Ok(Err(error)) if error.is_timeout() => HttpError::timeout(),
                Ok(Err(error)) => HttpError::connection(error),
                Err(_elapsed) => HttpError::timeout(),
            };
            if retries_remaining == 0 {
                return Err(error);
            }
            tracing::debug!("error=<{error}>, retries_remaining=<{retries_remaining}> | connection failed, retrying");
            let delay = retry_delay(None, retries_remaining, max_retries, self.random.as_ref());
            self.sleeper.sleep(delay).await;
            retries_remaining -= 1;
        }
    }
}

/// Checks that `base_url` is an absolute `http` or `https` URL, so a typo fails at construction
/// instead of as a retried connection error on every request.
fn validate_base_url(base_url: &str) -> Result<(), HttpError> {
    let parsed = reqwest::Url::parse(base_url)
        .map_err(|error| HttpError::request(format!("invalid base url '{base_url}': {error}"), Some(error.into())))?;
    if !matches!(parsed.scheme(), "http" | "https") || !parsed.has_host() {
        return Err(HttpError::request(
            format!("invalid base url '{base_url}': expected an http or https url"),
            None,
        ));
    }
    Ok(())
}

/// Reads an error response into an [`HttpError`].
async fn status_error(response: reqwest::Response, payload: ErrorPayload) -> HttpError {
    let status = response.status().as_u16();
    let text = match response.text().await {
        Ok(text) => text,
        Err(error) => error.to_string(),
    };
    let body = serde_json::from_str(&text).ok();
    HttpError::status(status, body, &text, payload)
}

/// Whether the SDK retry policy retries an error response.
pub(crate) fn should_retry(status: u16, headers: &HeaderMap) -> bool {
    match headers.get("x-should-retry").and_then(|value| value.to_str().ok()) {
        Some("true") => return true,
        Some("false") => return false,
        _ => {}
    }
    matches!(status, 408 | 409 | 429) || status >= 500
}

/// The wait before the next attempt: `retry-after-ms`, else
/// `retry-after` (seconds or an HTTP date), else the exponential default.
pub(crate) fn retry_delay(
    headers: Option<&HeaderMap>,
    retries_remaining: u32,
    max_retries: u32,
    random: &(dyn Fn() -> f64 + Send + Sync),
) -> Duration {
    let header = |name: &str| {
        headers
            .and_then(|headers| headers.get(name))
            .and_then(|value| value.to_str().ok())
            .filter(|value| !value.is_empty())
    };
    let mut millis = header("retry-after-ms").and_then(parse_js_float);
    if let Some(retry_after) = header("retry-after").filter(|_| millis.is_none_or(|millis| millis == 0.0)) {
        millis = Some(match parse_js_float(retry_after) {
            Some(seconds) => seconds * 1000.0,
            None => http_date_millis_from_now(retry_after).unwrap_or(f64::NAN),
        });
    }
    let millis = millis.unwrap_or_else(|| default_retry_millis(retries_remaining, max_retries, random()));
    duration_from_js_millis(millis)
}

/// The SDKs' default retry wait: 0.5 s doubling per retry up to 8 s, less up to 25 % jitter.
fn default_retry_millis(retries_remaining: u32, max_retries: u32, random: f64) -> f64 {
    let retries = max_retries.saturating_sub(retries_remaining);
    let seconds = (INITIAL_RETRY_DELAY_SECONDS * 2f64.powi(i32::try_from(retries).unwrap_or(i32::MAX)))
        .min(MAX_RETRY_DELAY_SECONDS);
    let jitter = 1.0 - random * MAX_JITTER;
    seconds * jitter * 1000.0
}

/// A delay in milliseconds: negative, infinite and `NaN` delays are immediate.
fn duration_from_js_millis(millis: f64) -> Duration {
    if !millis.is_finite() || millis <= 0.0 {
        return Duration::ZERO;
    }
    Duration::try_from_secs_f64(millis / 1000.0).unwrap_or(Duration::MAX)
}

/// Lenient float parsing: the longest decimal number at the start of `text`, after leading whitespace.
fn parse_js_float(text: &str) -> Option<f64> {
    let text = text.trim_start();
    let bytes = text.as_bytes();
    let mut end = 0;
    if matches!(bytes.first(), Some(b'+' | b'-')) {
        end += 1;
    }
    if text[end..].starts_with("Infinity") {
        return text[..end + "Infinity".len()].replace("Infinity", "inf").parse().ok();
    }
    let digits = |from: usize| bytes[from..].iter().take_while(|byte| byte.is_ascii_digit()).count();
    let integer = digits(end);
    end += integer;
    let mut fraction = 0;
    if bytes.get(end) == Some(&b'.') {
        fraction = digits(end + 1);
        if integer > 0 || fraction > 0 {
            end += 1 + fraction;
        }
    }
    if integer == 0 && fraction == 0 {
        return None;
    }
    if matches!(bytes.get(end), Some(b'e' | b'E')) {
        let sign = usize::from(matches!(bytes.get(end + 1), Some(b'+' | b'-')));
        let exponent = digits(end + 1 + sign);
        if exponent > 0 {
            end += 1 + sign + exponent;
        }
    }
    text[..end].parse().ok()
}

/// Milliseconds from now until an HTTP date (`Date.parse(value) - Date.now()`).
fn http_date_millis_from_now(value: &str) -> Option<f64> {
    let date = jiff::fmt::rfc2822::parse(value).ok()?;
    let millis = date.timestamp().duration_since(jiff::Timestamp::now()).as_millis();
    Some(millis as f64)
}

/// One server-sent event.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct SseEvent {
    /// The event name; `message` when the server sent none.
    pub(crate) event: String,
    /// The event data, with multi-line data joined by newlines.
    pub(crate) data: String,
}

/// The server-sent events of a streaming response. A read failure ends the stream with a
/// connection error; malformed event framing with a decode error.
pub(crate) fn sse_events(response: reqwest::Response) -> BoxStream<'static, Result<SseEvent, HttpError>> {
    let events = response.bytes_stream().eventsource();
    Box::pin(events.map(|event| match event {
        Ok(event) => Ok(SseEvent {
            event: if event.event.is_empty() {
                "message".to_owned()
            } else {
                event.event
            },
            data: event.data,
        }),
        Err(EventStreamError::Transport(error)) => Err(HttpError::connection(error)),
        Err(EventStreamError::Utf8(error)) => Err(HttpError::decode(error.to_string(), error)),
        Err(EventStreamError::Parser(error)) => {
            let message = error.to_string();
            Err(HttpError::decode(message.clone(), message))
        }
    }))
}

/// Reads a JSON response body.
///
/// # Errors
///
/// Returns a connection error when the body cannot be read and a decode error when it is not JSON.
#[allow(dead_code, reason = "the Anthropic provider reads JSON responses")]
pub(crate) async fn json_body(response: reqwest::Response) -> Result<JsonValue, HttpError> {
    let text = response.text().await.map_err(HttpError::connection)?;
    serde_json::from_str(&text).map_err(|error| HttpError::decode(error.to_string(), error))
}

/// A header map from name and value pairs. A later pair replaces an earlier one with the same
/// name, in any case, as the SDKs do.
///
/// # Errors
///
/// Returns a request error naming the first pair that is not a valid HTTP header, such as a value
/// with a line break. The error never holds the value, which may be a credential.
pub(crate) fn header_map<'a>(pairs: impl IntoIterator<Item = (&'a str, &'a str)>) -> Result<HeaderMap, HttpError> {
    let mut headers = HeaderMap::new();
    for (name, value) in pairs {
        let name_value = HeaderName::try_from(name)
            .map_err(|error| HttpError::request(format!("invalid http header name '{name}'"), Some(error.into())))?;
        let header_value = HeaderValue::try_from(value).map_err(|error| {
            HttpError::request(format!("invalid value for http header '{name}'"), Some(error.into()))
        })?;
        headers.insert(name_value, header_value);
    }
    Ok(headers)
}

/// Names of headers whose values are credentials, matched case-insensitively.
const SECRET_HEADERS: [&str; 5] = ["authorization", "proxy-authorization", "x-api-key", "api-key", "cookie"];

/// Debug view of name and value pairs that redacts credential headers (`authorization`,
/// `proxy-authorization`, `x-api-key`, `api-key`, `cookie`).
pub(crate) struct RedactedHeaders<'a>(pub(crate) &'a [(String, String)]);

impl std::fmt::Debug for RedactedHeaders<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_list()
            .entries(self.0.iter().map(|(name, value)| {
                let secret = SECRET_HEADERS.iter().any(|secret| name.eq_ignore_ascii_case(secret));
                (name.as_str(), if secret { "<redacted>" } else { value.as_str() })
            }))
            .finish()
    }
}

/// Parses a `<PROVIDER>_CUSTOM_HEADERS` value: one `name: value` per line, as the SDKs read it.
pub(crate) fn parse_custom_headers(value: &str) -> Vec<(String, String)> {
    value
        .split('\n')
        .filter_map(|line| line.split_once(':'))
        .map(|(name, value)| (name.trim().to_owned(), value.trim().to_owned()))
        .collect()
}

/// Reads an environment variable through `env` as the SDKs do: trimmed, and unset when blank.
pub(crate) fn read_env(env: &dyn Fn(&str) -> Option<String>, name: &str) -> Option<String> {
    env(name)
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
}

